const std = @import("std");

pub fn main() !void {
    const text = "hello world";
    var freq: [256]u32 = [_]u32{0} ** 256;

    for (text) |ch| {
        freq[ch] += 1;
    }

    for (text) |ch| {
        if (freq[ch] > 0) {
            std.debug.print("{c}:{} ", .{ch, freq[ch]});
            freq[ch] = 0;
        }
    }
    std.debug.print("\n", .{});
}
